package io.github.jesterportfolio.hearth.combat;

import io.github.jesterportfolio.hearth.persistence.ServerProgressAccess.Context;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import static io.github.jesterportfolio.hearth.combat.CombatContent.*;

/** 기존 전투 상태와 실제 세션 적용 사이의 작은 경계. 인벤토리를 별도 저장하지 않습니다. */
public final class CombatPlayers implements CombatAttempt.Port,AutoCloseable {
    public interface PlayerPort {
        Context context();Object session();Pose position();boolean current();
        void spectator(UUID target);void clearCamera();void cleanup();
        boolean safe(Pose position);
        CompletionStage<Boolean> restore(Pose position,double health,List<Effect> effects,BooleanSupplier current);
    }
    private final UUID run,world;private final long generation;private final LongSupplier currentGeneration;private final Executor owner;private final Runnable check;
    private final Map<UUID,PlayerPort> players=new HashMap<>();private final Map<UUID,Long> projected=new HashMap<>();private final Map<PlayerPort,Set<CompletableFuture<Boolean>>> pending=new IdentityHashMap<>();private CombatAttempt attempt;private boolean closed;private volatile boolean deliveryFailed;
    public CombatPlayers(UUID run,UUID world,long generation,LongSupplier currentGeneration,Executor owner,Runnable check){this.run=run;this.world=world;this.generation=generation;this.currentGeneration=currentGeneration;this.owner=owner;this.check=check;}
    public void attach(CombatAttempt attempt,List<PlayerPort> online){check.run();if(this.attempt!=null||closed||!attempt.snapshot().run().equals(run)||attempt.snapshot().generation()!=generation)throw new IllegalStateException("COMBAT_BINDING_REJECTED");this.attempt=attempt;try{for(var p:online){if(!p.context().storyRunId().equals(run)||!p.position().world().equals(world)||!p.current()||players.putIfAbsent(p.context().playerId(),p)!=null)throw new IllegalStateException("COMBAT_PLAYER_REJECTED");attempt.view(p.context(),p.session());}if(players.size()!=attempt.snapshot().difficultyPlayers())throw new IllegalStateException("COMBAT_ROSTER_MISMATCH");project();}catch(RuntimeException error){attempt.invalidate();throw error;}}
    public boolean current(PlayerPort p){check.run();return !closed&&!deliveryFailed&&currentGeneration.getAsLong()==generation&&players.get(p.context().playerId())==p&&p.current()&&p.position().world().equals(world);}
    private CombatAttempt.Member member(PlayerPort p){attempt.view(p.context(),p.session());return attempt.snapshot().members().stream().filter(m->m.player().equals(p.context().playerId())).findFirst().orElseThrow();}
    public boolean actions(PlayerPort p){check.run();if(!current(p))return false;try{var m=member(p);return attempt.playable(p.context(),p.session())||attempt.snapshot().phase()==CombatAttempt.Phase.CLOSED&&attempt.snapshot().error()==null&&!m.dead()&&!m.reviving();}catch(RuntimeException e){return false;}}
    public static boolean safeCells(String below,String feet,String head,boolean solidFloor,boolean freeFeet,boolean freeHead){var hazards=Set.of("LAVA","FIRE","SOUL_FIRE","CACTUS","MAGMA_BLOCK","CAMPFIRE","SOUL_CAMPFIRE","POWDER_SNOW","SWEET_BERRY_BUSH","WITHER_ROSE");return solidFloor&&freeFeet&&freeHead&&!hazards.contains(below)&&!hazards.contains(feet)&&!hazards.contains(head);}
    public static double restoredHealth(double maximum,double fraction){double health=maximum*fraction;if(!Double.isFinite(maximum)||maximum<=0||!Double.isFinite(fraction)||fraction<=0||fraction>1||!Float.isFinite((float)health)||(float)health<=0)throw new IllegalStateException("COMBAT_INVALID_RESTORE_HEALTH");return health;}
    public boolean movement(PlayerPort p){check.run();if(!current(p))return false;try{var m=member(p);return !m.returning()&&!m.reviving()&&(m.dead()||actions(p));}catch(RuntimeException e){return false;}}
    public Optional<Pose> returnPosition(Context ctx){check.run();if(closed||currentGeneration.getAsLong()!=generation)return Optional.empty();return attempt.returnPosition(ctx);}
    public void rejoin(PlayerPort p){check.run();if(closed||!p.current()||!run.equals(p.context().storyRunId())||!world.equals(p.position().world())||currentGeneration.getAsLong()!=generation)throw new IllegalStateException("COMBAT_REJOIN_REJECTED");if(players.containsKey(p.context().playerId()))throw new IllegalStateException("COMBAT_DUPLICATE_REJOIN");players.put(p.context().playerId(),p);try{Pose expected=attempt.reconnect(p.context(),p.session());if(!samePosition(expected,p.position()))throw new IllegalStateException("COMBAT_RETURN_NOT_APPLIED");attempt.returned(p.context(),p.session());projected.remove(p.context().playerId());project();}catch(RuntimeException e){attempt.invalidate();throw e;}}
    public static boolean samePosition(Pose a,Pose b){return a.world().equals(b.world())&&Math.abs(a.x()-b.x())<0.000001&&Math.abs(a.y()-b.y())<0.000001&&Math.abs(a.z()-b.z())<0.000001&&Math.abs(Math.IEEEremainder((double)a.yaw()-b.yaw(),360))<0.001&&Math.abs(a.pitch()-b.pitch())<0.001;}
    public void died(PlayerPort p){check.run();if(!actions(p))throw new IllegalStateException("COMBAT_PLAYER_NOT_ACTIVE");attempt.died(p.context(),p.session(),p.position());projected.remove(p.context().playerId());}
    public void leave(PlayerPort p){check.run();if(players.get(p.context().playerId())!=p)return;try{attempt.disconnect(p.context(),p.session(),p.position());}catch(RuntimeException e){attempt.invalidate();throw e;}finally{players.remove(p.context().playerId(),p);projected.remove(p.context().playerId());var jobs=pending.remove(p);if(jobs!=null)jobs.forEach(job->job.completeExceptionally(new IllegalStateException("COMBAT_SESSION_LEFT")));try{p.cleanup();}catch(RuntimeException error){deliveryFailed=true;attempt.invalidate();throw error;}}}
    public void project(){check.run();if(closed||attempt==null)return;if(deliveryFailed||currentGeneration.getAsLong()!=generation){attempt.invalidate();return;}var snapshot=attempt.snapshot();for(var p:List.copyOf(players.values()))if(current(p)&&!Objects.equals(projected.get(p.context().playerId()),snapshot.revision()))try{var m=member(p);if(m.reviving()||m.returning())continue;if(m.dead())p.spectator(snapshot.phase()==CombatAttempt.Phase.HOLD?null:m.camera());else p.clearCamera();projected.put(p.context().playerId(),snapshot.revision());}catch(RuntimeException e){attempt.invalidate();throw e;}}
    public CompletionStage<Void> barrier(){check.run();var jobs=pending.values().stream().flatMap(Set::stream).toArray(CompletableFuture[]::new);return CompletableFuture.allOf(jobs).thenCompose(v->attempt==null?CompletableFuture.completedFuture(null):attempt.barrier()).thenRun(()->{check.run();if(deliveryFailed)throw new IllegalStateException("COMBAT_PLAYER_HOLD");});}
    public CombatAttempt attempt(){check.run();return Objects.requireNonNull(attempt);}
    public void freeze(boolean paused){check.run();}
    public void camera(UUID player,UUID target){check.run();projected.remove(player);}
    public boolean safe(Pose position){check.run();return !closed&&position.world().equals(world)&&players.values().stream().anyMatch(p->current(p)&&p.safe(position));}
    public CompletionStage<Boolean> revive(UUID player,Pose position,double health,List<Effect> effects,BooleanSupplier valid){check.run();var p=players.get(player);if(p==null||!current(p))return CompletableFuture.failedFuture(new IllegalStateException("COMBAT_PLAYER_STALE"));var result=new CompletableFuture<Boolean>();pending.computeIfAbsent(p,k->new HashSet<>()).add(result);BooleanSupplier guard=()->!result.isDone()&&current(p)&&valid.getAsBoolean();CompletionStage<Boolean> work;try{work=Objects.requireNonNull(p.restore(position,health,effects,guard),"Missing combat restore result");}catch(RuntimeException e){work=CompletableFuture.failedFuture(e);}work.whenCompleteAsync((ok,error)->{try{if(result.isDone())return;if(error!=null)result.completeExceptionally(error);else result.complete(guard.getAsBoolean()&&Boolean.TRUE.equals(ok));}finally{var jobs=pending.get(p);if(jobs!=null){jobs.remove(result);if(jobs.isEmpty())pending.remove(p);}}},owner).exceptionally(error->{deliveryFailed=true;result.completeExceptionally(error);return null;});return result;}
    @Override public void close(){check.run();if(closed)return;closed=true;if(attempt!=null&&attempt.snapshot().phase()!=CombatAttempt.Phase.CLOSED)attempt.finish(CombatAttempt.Outcome.RETIRED);for(var jobs:pending.values())jobs.forEach(job->job.completeExceptionally(new IllegalStateException("COMBAT_PLAYER_CLOSED")));pending.clear();RuntimeException failure=null;for(var p:List.copyOf(players.values()))try{p.cleanup();}catch(RuntimeException e){deliveryFailed=true;if(failure==null)failure=e;else failure.addSuppressed(e);}players.clear();projected.clear();if(failure!=null)throw failure;}
}
